class Solution {
    public int editDistance(String start, String target) {
        int n = start.length();
        int m = target.length();
        int[] prev = new int[m+1];
        int[] curr = new int[m+1];

        for (int j = 0; j <= m; j++) prev[j] = j;

        for (int i = 1; i <=n; i++) {
            curr[0] = i;
            for (int j = 1; j <=m; j++) {
                if(start.charAt(i-1) == target.charAt(j-1)){
                    curr[j] = prev[j-1];
                }else{
                    int insert = curr[j-1];
                    int delete = prev[j];
                    int replace = prev[j-1];
                    curr[j] = 1 + Math.min(insert, Math.min(delete, replace));
                }
            }
            prev=curr;
            curr = new int[m+1];
        }
        return prev[m];
    }
}

